import uploadPictures from "@/components/uploadPictures";
import OperationFloorModal from "@/components/hotpotModal";
export default {
  name: "c_one_pictrue",
  components: {
    uploadPictures,
    OperationFloorModal,
  },
  props: {
    configObj: {
      type: Object,
    },
    configNme: {
      type: String,
    },
  },
  data() {
    return {
      defaults: {},
      configData: {
        list:[]
      },
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      modalPic: false,
      isChoice: "单选",
      imgAreaData: [], //热区数据
    };
  },
  watch: {
    configObj: {
      handler(nVal, oVal) {
        this.configData = nVal.picStyle;
        this.defaults = nVal;
        this.$set(this,'imgAreaData',nVal.picStyle.list);
      },
      deep: true,
    },
  },
  mounted() {
    this.$nextTick(() => {
      this.defaults = this.configObj;
      this.configData = this.configObj[this.configNme];
      this.imgAreaData = this.configObj.picStyle.list;
    });
  },
  methods: {
    bindDelete() {
      this.configData.url = "";
    },
    // 点击图文封面
    modalPicTap(title) {
      this.modalPic = true;
    },
    // 获取图片信息
    getPic(pc) {
      this.$nextTick(() => {
        this.configData.url = pc.att_dir;
        this.configData.list = [];
        this.imgAreaData = [];
        this.modalPic = false;
      });
    },
    openFloorModal() {
      // 如果配置数据中有url，则显示热点图对话框
      if (this.configData.url) this.$refs.hotpot.dialogVisible = true;
    },
    /**
     * 处理区域数据
     * @param {Object} areaData - 区域数据对象
     */
    handleAreaData(areaData) {
      // 打印保存的数据
      this.configData.list = areaData;
      console.log(this.configData.list,'list');
    },
  },
};
